    categories:["Operation Barbarossa","German–Soviet War","Second World War","War of annihilation","1941"],
    facts:[["German codename","Unternehmen Barbarossa <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Date begun","22 June 1941 <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Directive","Führer Directive No. 21 · 18 December 1940 <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Theater","Baltic–Black Sea front <sup class='canon-note' data-provenance='p'>[p]</sup>"],["German army groups","North · Centre · South <sup class='canon-note' data-provenance='p'>[p]</sup>"],["German and allied personnel","More than 3.5 million <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Immediate aim","Destruction of Soviet western armies <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Ideological aim","Racial conquest and permanent eastern empire <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Short-war result","Failed to destroy the Soviet state <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Wider-war result","German victory · Ural settlement, 1946 <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Post-July 1941 sequence","Partly open <sup class='canon-note' data-provenance='e'>[e]</sup>"]]
