    categories:["Panzer Group 1","German armored formations","Army Group South","Operation Barbarossa","Battle of Uman"],
    facts:[["German name","Panzergruppe 1 <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Service","German Army <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Type","Armored operational headquarters <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Commander on 31 July","Colonel General Ewald von Kleist <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Superior command","Army Group South <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Opening organization","Five panzer divisions plus motorized, infantry, and SS formations <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Major inherited battle","Brody–Dubno counteroffensive <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Historical Uman closure","Not inherited automatically <sup class='canon-note' data-provenance='e'>[e]</sup>"],["Associated air command","Luftflotte 4 <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Historical successor","First Panzer Army <sup class='canon-note' data-provenance='e'>[e]</sup>"],["In-setting redesignation date","Open <sup class='canon-note' data-provenance='e'>[e]</sup>"]]
